MOD = 1_000_000_007

def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    # ----- build Aho‑Corasick automaton -----
    # each node: dict child, fail link, output flag
    trie = [{'next': {}, 'fail': 0, 'out': False}]
    for pat in banned:
        node = 0
        for ch in pat:
            if ch not in trie[node]['next']:
                trie[node]['next'][ch] = len(trie)
                trie.append({'next': {}, 'fail': 0, 'out': False})
            node = trie[node]['next'][ch]
        trie[node]['out'] = True

    # build failure links
    from collections import deque
    q = deque()
    for ch, nxt in trie[0]['next'].items():
        q.append(nxt)
        trie[nxt]['fail'] = 0

    while q:
        v = q.popleft()
        # propagate output flag
        if trie[trie[v]['fail']]['out']:
            trie[v]['out'] = True
        for ch, nxt in trie[v]['next'].items():
            f = trie[v]['fail']
            while f and ch not in trie[f]['next']:
                f = trie[f]['fail']
            trie[nxt]['fail'] = trie[f]['next'].get(ch, 0)
            q.append(nxt)

    # ----- pre‑compute transitions for each state and each alphabet character -----
    m = len(trie)                     # number of states
    trans = [[0] * m for _ in range(m)]   # trans[i][j] = number of chars leading i -> j
    for i in range(m):
        if trie[i]['out']:
            continue          # dead state, no outgoing contributions
        for ch in alphabet:
            v = i
            while v and ch not in trie[v]['next']:
                v = trie[v]['fail']
            v = trie[v]['next'].get(ch, 0)
            if not trie[v]['out']:
                trans[i][v] += 1   # this character leads to a safe state

    # ----- matrix exponentiation -----
    def mat_mul(A, B):
        size = len(A)
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            Ai = A[i]
            Ci = C[i]
            for k in range(size):
                aik = Ai[k]
                if aik:
                    Bk = B[k]
                    for j in range(size):
                        if Bk[j]:
                            Ci[j] = (Ci[j] + aik * Bk[j]) % MOD
        return C

    def mat_pow(mat, power):
        size = len(mat)
        # identity matrix
        res = [[1 if i == j else 0 for j in range(size)] for i in range(size)]
        while power:
            if power & 1:
                res = mat_mul(res, mat)
            mat = mat_mul(mat, mat)
            power >>= 1
        return res

    if n == 0:
        return 1

    M = trans
    Mexp = mat_pow(M, n)

    # initial vector has 1 at root (state 0)
    # result vector = row 0 of Mexp (since v0 * M^n)
    answer = sum(Mexp[0]) % MOD
    return answer
```

This implementation builds an Aho‑Corasick automaton for the forbidden substrings, constructs a transition matrix that counts safe moves for each character, raises it to the n‑th power with fast exponentiation, and finally sums the ways to end in any non‑banned state. It works for `n` up to `10¹⁸` and respects the required modulo.
